export function cartLinesDiscountsGenerateRun(input) {
  const dob = input.cart.buyerIdentity?.customer?.metafield?.value;
  const today = new Date();
  const birthday = dob ? new Date(dob) : null;
  const isBirthday = birthday
    && birthday.getMonth() === today.getMonth()
    && birthday.getDate() === today.getDate();

  if (!isBirthday) return { operations: [] };

  return {
    operations: [{
      orderDiscountsAdd: {
        selectionStrategy: "FIRST",
        candidates: [{
          message: "Feliz aniversário! 15% OFF",
          targets: [{ orderSubtotal: { excludedCartLineIds: [] } }],
          value: { percentage: { value: "15.0" } }
        }]
      }
    }]
  };
}

